"OLAYLAR_ARKEOLOJI_D3_AMERIKA_PASIFIK:-4349-01-01:0":{"b": ["Pha Coxcatlán (thung lũng Tehuacán): chấm dứt", "04287f43"], "d": ["Một pha ở thung lũng Tehuacán, tiếp sau El Riego thuộc Holocen sớm và trước Abejas; được mô hình hóa bằng các mẫu 14C từ các hang Coxcatlán, Purrón và San Marcos.", "510a7683"]},
"OLAYLAR_ARKEOLOJI_D3_AMERIKA_PASIFIK:-5949-01-01:0":{"b": ["Pha Coxcatlán (thung lũng Tehuacán): Tehuacán: pha Coxcatlán", "7ed889cc"], "d": ["Một pha ở thung lũng Tehuacán, tiếp sau El Riego thuộc Holocen sớm và trước Abejas; được mô hình hóa bằng các mẫu 14C từ các hang Coxcatlán, Purrón và San Marcos.", "510a7683"]},
"OLAYLAR_ARKEOLOJI_D3_ANADOLU_EGE:-0899-01-01:0":{"b": ["Vương quốc Urartu (Tushpa / Van): nhà nước Urartu hình thành (thế kỷ 9)", "3dec342f"], "d": ["Nhà nước Urartu hình thành vào thế kỷ 9 TCN. Trong các nguồn Assyria có những cuộc chiến của Shalmaneser III với Arame; Sarduri I (con của Lutipri) lấy Tushpa làm kinh đô.", "72d6f79a"]},
"OLAYLAR_ARKEOLOJI_D3_ANADOLU_EGE:-1190-01-01:0":{"b": ["Vương quốc Ugarit (Gibala/Tell Tweini) — sự tàn phá của Các dân tộc Biển: Ugarit/Tell Tweini bị phá hủy (thời Các dân tộc Biển)", "eb558ed2"], "d": ["Các đợt tàn phá cuối thời Đồ đồng ở bắc Levant (Gibala, Ugarit, Ras Ibn Hani, Tell Kazel); là 1192-1190 cal BC trong khung gồm trung bình có trọng số 14C (2962±14 BP) + nhật thực trong KTU 1.78 (21 tháng 1 năm 1192).", "720ed864"]},
"OLAYLAR_ARKEOLOJI_D3_ANADOLU_EGE:-1199-01-01:0":{"b": ["Cuộc rời bỏ Hattusa — ghi chú đọc đợt 3: Hattusa bị bỏ; Đế quốc Hittite sụp đổ (khoảng 1200)", "bdfe8ed5"], "d": ["Chính quyền trung ương đã rời khỏi Hattusa, còn thành phố chỉ bị đốt SAU ĐÓ; hạn hán (1198-1196±3) có thể là một phần trong bối cảnh sụp đổ, nhưng KHÔNG có quan hệ nhân quả nào được chứng minh.", "6d29b755"]},
"OLAYLAR_ARKEOLOJI_D3_ANADOLU_EGE:-1206-01-01:0":{"b": ["Suppiluliuma II (vua Hittite cuối cùng được biết) — lên ngôi: Suppiluliuma II lên ngôi (vua Hittite cuối cùng)", "b2ef7227"], "d": ["Triều đại của vị vua Hittite cuối cùng được biết bắt đầu ~1207 TCN; đế quốc Hittite và chính quyền trung ương sụp đổ 'around or shortly after 1200' (khoảng hoặc ngay sau 1200); terminus ante quem là năm thứ 8 của Ramses III (Medinet Habu).", "77bdf879"]},
"OLAYLAR_ARKEOLOJI_D3_ANADOLU_EGE:-1583-01-01:0":{"b": ["Vụ phun trào thời Minos ở Thera (Santorini) — các mô hình Bayes hiện hành: vụ phun trào Thera (Santorini) — mô hình Manning 2022", "a63eeb92"], "d": ["Vụ phun trào được mô hình hóa lại với IntCal20: 1606-1589 (68.3) / 1609-1560 (95.4). Bruins & van der Plicht 2025 (PLoS One, doi:10.1371/journal.pone.0330702) dẫn mô hình 2024 của Manning là 1618-1584 (95.4) / 1612-1602 (68.3) và lập luận rằng vụ phun trào CỔ HƠN Ahmose.", "94d58c09"]},
"OLAYLAR_ARKEOLOJI_D3_ANADOLU_EGE:-1649-01-01:0":{"b": ["Cổ Vương quốc Hittite — triều đại Hattusili I (Labarna): thời Hattusili I (giá trị truyền thống hMC)", "17b63f56"], "d": ["Triều đại truyền thống của Hattusili I theo hMC là khoảng 1650-1620; mốc bắt đầu được tính bằng cách đếm lùi hai thế hệ 25 năm từ dữ kiện Babylon 1595 của Mursili. Vương quốc Hittite đã thống nhất Trung Anatolia vào cuối thời Đồ đồng giữa.", "8b5469d2"]},
"OLAYLAR_ARKEOLOJI_D3_ANADOLU_EGE:-1749-01-01:0":{"b": ["Troy V và đầu Troy VI (VIa): cuối Troy V / đầu VI (giá trị đồng thuận)", "c74e35b0"], "d": ["Thời điểm bắt đầu Troy V nằm trong khoảng 1916-1877 cal BC; đối với cuối Troy V / đầu Troy VI, giới nghiên cứu đồng thuận khoảng 1750 cal BC (dẫn Pavúk, Blum, Pernicka).", "0d91aab0"]},
