"OLAYLAR_ARKEOLOJI_D3_HINT_CIN:-4899-01-01:0":{"b": ["Jiangzhai (Ngưỡng Thiều, làng có hào vòng thuộc pha Bán Pha): điểm định cư Jiangzhai (Ngưỡng Thiều)", "8bc69159"], "d": ["Làng có hào vòng thuộc văn hóa Ngưỡng Thiều; trong bản tổng hợp đồng vị, 20 cá thể được lấy mẫu.", "8512e2c8"]},
"OLAYLAR_ARKEOLOJI_D3_HINT_CIN:-5999-01-01:0":{"b": ["Thời kỳ Chulmun (Đồ đá mới Triều Tiên): thời kỳ Chulmun bắt đầu (Triều Tiên)", "e932ac2d"], "d": ["Thời kỳ săn bắt-hái lượm-đánh cá có đồ gốm ở Triều Tiên; sự chuyển tiếp Chulmun/Mumun diễn ra đột ngột và ở quy mô khu vực.", "2190b73a"]},
"OLAYLAR_ARKEOLOJI_D3_ITALYA_AVRUPA:-0507-01-01:0":{"b": ["La Mã: Vương chính -> Cộng hòa (các chấp chính quan đầu tiên) - TRUYỀN THỐNG THÀNH VĂN: La Mã: Vương chính chấm dứt, Cộng hòa (theo truyền thống)", "912914d1"], "d": ["Polybios và Dionysios đặt sự chấm dứt của Vương chính và các chấp chính quan đầu tiên vào cùng một năm; ba phép tính nội bộ độc lập (Polybios/Xerxes, Dionysios/120 năm sau người Gaul, Dionysios/244 năm vương chính) đều ra năm 508 TCN.", "59449f95"]},
"OLAYLAR_ARKEOLOJI_D3_ITALYA_AVRUPA:-0669-01-01:0":{"b": ["Chuyển tiếp Hallstatt C -> D (mô hình Bayes Dietfurt; truyền thống 616): chuyển tiếp Hallstatt C → D (mô hình 14C)", "e02fb9ba"], "d": ["Ở nam Đức, theo mô hình Bayes của chuỗi mộ Dietfurt, sự chuyển từ Ha C sang Ha D diễn ra trước 650 cal BC và rất có thể trong khoảng 685-655; sớm hơn vài chục năm so với mốc được chấp nhận rộng rãi.", "dcfea6b4"]},
"OLAYLAR_ARKEOLOJI_D3_ITALYA_AVRUPA:-0751-01-01:0":{"b": ["Thành lập La Mã (niên đại theo TRUYỀN THỐNG THÀNH VĂN): La Mã được lập (truyền thống thành văn, Dionysios)", "1d943e4c"], "d": ["Truyền thống thành văn đặt việc lập La Mã, theo cách tính Olympiad, vào năm thứ 1 của Olympiad thứ 7 (Cato, Dionysios) - giữa các tác giả dao động từ 7.1 đến 12.4. Niên đại 753 của Varro chưa được đọc TỪ NGUỒN trong phiên làm việc này.", "181d376a"]},
"OLAYLAR_ARKEOLOJI_D3_ITALYA_AVRUPA:-0759-01-01:0":{"b": ["Carthage - truyền thống thành lập 814/813 đối chiếu khảo cổ ~760: Carthage: khởi đầu cư trú liên tục (khảo cổ)", "ee345ccd"], "d": ["Sự thành lập huyền thoại của Carthage (Elissa/Dido) là 814-813; trong thành phố, khai quật cho thấy cư trú liên tục bắt đầu khoảng 760 TCN, các mộ cổ nhất thuộc nửa sau thế kỷ 8; khu nghĩa địa thế kỷ 8 vẫn chưa được tìm thấy.", "9c450808"]},
"OLAYLAR_ARKEOLOJI_D3_ITALYA_AVRUPA:-0836-01-01:0":{"b": ["Latium Vetus: chuyển tiếp Latial II -> III (truyền thống ~770 đối chiếu niên biểu cao theo 14C 850-825): Latium: chuyển tiếp Latial II → III (niên biểu cao)", "d589d124"], "d": ["Ở trung Ý (Latium Vetus) thời Đồ sắt sớm, theo hình thái-niên biểu truyền thống, sự chuyển từ Latial II sang III là ~770 TCN; 14C của các mẫu có đời sống ngắn (hạt ở Fidene) kéo mốc chuyển tiếp về phần tư thứ ba thế kỷ 9 TCN (850-825).", "0ed2a01a"]},
"OLAYLAR_ARKEOLOJI_D3_ITALYA_AVRUPA:-0929-01-01:0":{"b": ["Thời kỳ Hình học Hy Lạp (niên đại tuyệt đối được đẩy sớm theo 14C): Hình học Trung kỳ II bắt đầu (14C Sindos: 930 so với truyền thống 800)", "900bbb4b"], "d": ["Chuỗi 14C xương động vật theo địa tầng tại Sindos ở bắc Hy Lạp đẩy các niên đại tuyệt đối truyền thống của các phân kỳ Hình học (dựa trên niên đại các thuộc địa ở Sicilia) sớm lên 100-150 năm; khởi đầu MG II là 930 calBC thay vì 800 histBC.", "d21e4714"]},
"OLAYLAR_ARKEOLOJI_D3_MISIR_AFRIKA:-0029-01-01:0":{"b": ["Khởi đầu Ai Cập thuộc La Mã - Octavianus chiếm Alexandria: La Mã chiếm Ai Cập (Octavianus)", "6ddd4666"], "d": ["Tháng 8 năm 30 TCN: Octavianus chiếm Alexandria; 'kratesis' chính thức được tính từ ngày 1 Thoth = 29 tháng 8 năm 30 TCN (khép lại bằng 'triều đại' 18 ngày của các con Antonius).", "509e9fa3"]},
"OLAYLAR_ARKEOLOJI_D3_MISIR_AFRIKA:-0331-01-01:0":{"b": ["Thành lập Alexandria: Alexandria được lập (theo truyền thống)", "3fe6d34a"], "d": ["Alexandros lập thành phố bên cạnh điểm định cư Rhakotis; truyền thống ghi năm 331 (tháng 4), một số nguồn ghi 332.", "46a368d3"]},
"OLAYLAR_ARKEOLOJI_D3_MISIR_AFRIKA:-1079-01-01:0":{"b": ["Ai Cập Tân Vương quốc chinh phục Nubia / Ai Cập chiếm đóng (sau Kerma): cuộc chiếm đóng Nubia của Ai Cập chấm dứt", "8241bd37"], "d": ["Vương quốc Kerma bị các pharaon Tân Vương quốc chinh phục; kerma.ch quy cuộc chinh phục cho Thutmose I (1496-1483) và nêu rằng ảnh hưởng Ai Cập ở phía nam Thác thứ Ba chỉ được cảm nhận dưới thời Thutmose III (1479-1424).", "b10ad95e"]},
